function validate([pattern]) {
  if (typeof pattern !== 'string') return 'pattern must be a string.';
  if (pattern.length < 1 || pattern.length > 8) return 'pattern has 1 to 8 letters.';
  if (!/^[ID]+$/.test(pattern)) return "pattern may only contain 'I' and 'D'.";
  return null;
}

