function smallestNumber(pattern) {
  const n = pattern.length + 1;
  const used = new Array(10).fill(false);
  const digits = [];
  const search = () => {
    if (digits.length === n) return true;
    for (let d = 1; d <= 9; d++) {
      if (used[d]) continue;
      const k = digits.length;
      if (k > 0) {
        const prev = digits[k - 1];
        if (pattern[k - 1] === 'I' ? !(prev < d) : !(prev > d)) continue;
      }
      used[d] = true;
      digits.push(d);
      if (search()) return true;
      digits.pop();
      used[d] = false;
    }
    return false;
  };
  search();
  return digits.join('');
}

