function generate(rand, size) {
  const n = size === 'large' ? 8 : 1 + Math.floor(rand() * 8);
  const pDecrease = rand();
  let pattern = '';
  for (let i = 0; i < n; i++) pattern += rand() < pDecrease ? 'D' : 'I';
  return [pattern];
}
